static void lf_cfused_2x2_c2_f(const double *in, double *out) {
  const __m256d x0_0 = _mm256_loadu_pd(in + 0);
  const __m256d x0_1 = _mm256_loadu_pd(in + 4);
  const __m256d p0_u0 = _mm256_add_pd(x0_0, x0_1);
  const __m256d p0_u1 = _mm256_sub_pd(x0_0, x0_1);
  const __m256d c0_0_0 = _mm256_permute2f128_pd(p0_u0, p0_u1, 0x20);
  const __m256d c0_0_1 = _mm256_permute2f128_pd(p0_u0, p0_u1, 0x31);
  const __m256d w0_1 = _mm256_setr_pd(0x1.0000000000000p0, 0.0, 0.0, -0x1.0000000000000p0);
  const __m256d q0_u0 = _mm256_shuffle_pd(w0_1, w0_1, 0);
  const __m256d q0_u1 = _mm256_shuffle_pd(c0_0_1, c0_0_1, 5);
  const __m256d q0_u2 = _mm256_shuffle_pd(w0_1, w0_1, 15);
  const __m256d q0_u3 = _mm256_mul_pd(q0_u1, q0_u2);
  const __m256d q0_u4 = _mm256_fmaddsub_pd(c0_0_1, q0_u0, q0_u3);
  const __m256d q0_u5 = _mm256_add_pd(c0_0_0, q0_u4);
  const __m256d q0_u6 = _mm256_sub_pd(c0_0_0, q0_u4);
  _mm256_storeu_pd(out + 0, q0_u5);
  _mm256_storeu_pd(out + 4, q0_u6);
}

